  const ahead = Number(gitOut(source.path, ["rev-list", "--count", `${mergeBase}..HEAD`]));

  return {
    repo,
    source: source as WorktreeEntry & { branch: string },
    branch,
    targetName,
    targetEntry,
    targetSha,
    state,
    gateState,
    waiver,
    mergeBase,
    ahead,
  };
}

